        for (int p : primes) {
            long curP = p;
            while (n / curP > 0) {
                ans = (ans * power(p, n / curP)) % MOD;
                if ((curP * p) / p != curP) break;
                curP *= p;
            }
        }

        System.out.println(ans);
    }

    static boolean isPrime(int k) {
        if (k == 1) return false;
        if (k == 2 || k == 3) return true;
